// Dynamic search queries for AI adoption roles
const searchQueries = [
  {
    platform: 'linkedin',
    query: 'AI Adoption Specialist legal technology',
    location: 'United States',
    keywords: ['AI', 'adoption', 'legal', 'technology']
  },
  {
    platform: 'indeed',
    query: 'AI Training Manager legal compliance', 
    location: 'Remote',
    keywords: ['AI', 'training', 'legal', 'compliance']
  },
  {
    platform: 'linkedin',
    query: 'Technical Implementation Consultant AI',
    location: 'United States',
    keywords: ['technical', 'implementation', 'AI', 'consultant']
  },
  {
    platform: 'indeed',
    query: 'Generative AI specialist legal services',
    location: 'Remote',
    keywords: ['generative', 'AI', 'legal', 'services']
  },
  {
    platform: 'flexjobs',
    query: 'AI enablement training manager',
    location: 'Remote',
    keywords: ['AI', 'enablement', 'training']
  }
];

// Add timestamp and run ID
const runId = Math.random().toString(36).substring(2, 15);
const timestamp = new Date().toISOString();

return searchQueries.map((query, index) => ({
  ...query,
  runId,
  timestamp,
  queryIndex: index,
  totalQueries: searchQueries.length
}));

// Parse Crawl4AI output and structure job data
let crawlOutput;
try {
  crawlOutput = JSON.parse($json.stdout || '{}');
} catch (error) {
  console.error('Failed to parse Crawl4AI output:', error);
  return { error: 'Failed to parse crawler output', rawOutput: $json.stdout };
}

// Extract jobs from crawl output
const jobs = crawlOutput.jobs || crawlOutput.data || [];

// Structure each job consistently
const structuredJobs = jobs.map(job => ({
  // Core job info
  title: job.title || job.job_title || 'Unknown Position',
  company: job.company || job.company_name || 'Unknown Company',
  location: job.location || 'Not specified',
  description: job.description || job.job_description || '',
  url: job.url || job.job_url || '',

  // Additional metadata
  salary: job.salary || job.salary_range || null,
  posted_date: job.posted_date || job.date_posted || null,
  job_type: job.job_type || job.employment_type || 'Not specified',

  // Search context
  source: $json.platform || 'crawl4ai',
  search_query: $json.query,
  search_location: $json.location,
  keywords: $json.keywords,

  // Processing metadata
  discovered_at: new Date().toISOString(),
  run_id: $json.runId,
  query_index: $json.queryIndex,

  // Initialize pipeline stage
  pipeline_stage: 'To Review',
  ai_match_score: null, // Will be calculated next

  // Raw data for debugging
  raw_data: job
}));

// Log discovery stats
console.log(`Discovered ${structuredJobs.length} jobs from ${$json.platform} for query: ${$json.query}`);

return structuredJobs;

